-- Make Latent Diffusion and Proximal Policy Optimization resolve to their
-- existing method pages. Added 2026-10-20 after production chat users looked up
-- "latent-diffusion" and "proximal-policy-optimization" with pwc_get_method.
--
-- Stable Diffusion's source paper is the latent diffusion models paper
-- (2112.10752), so latent diffusion is an alias of stable-diffusion rather than
-- a separate method.

UPDATE methods
SET
    full_name = 'Stable Diffusion (Latent Diffusion Model)',
    description = 'Stable Diffusion is the open text-to-image model family built on latent diffusion models (LDMs), introduced by Rombach et al. in High-Resolution Image Synthesis with Latent Diffusion Models. A latent diffusion model trains the diffusion process in the compressed latent space of a pretrained autoencoder instead of pixel space, and conditions the denoising U-Net on text or other inputs through cross-attention, which cuts training and sampling cost enough to run on consumer hardware. Released by Stability AI, CompVis and Runway in 2022, Stable Diffusion made LDMs the default backbone for open image, video and audio generation and for editing and control methods such as [ControlNet](/methods/controlnet); later versions replace the U-Net with [MMDiT](/methods/mmdit) transformers and [rectified flow](/methods/rectified-flow) training.',
    keywords = 'stable diffusion, latent diffusion, latent diffusion model, LDM',
    updated_at = CURRENT_TIMESTAMP
WHERE slug = 'stable-diffusion';

UPDATE methods
SET
    full_name = 'Proximal Policy Optimization (PPO)',
    keywords = 'proximal policy optimization, proximal policy optimisation, PPO',
    updated_at = CURRENT_TIMESTAMP
WHERE slug = 'ppo';

